<script setup>
import { watch, ref, onMounted } from 'vue';
import { storeToRefs } from "pinia";
import { useFVStore } from '../../../stores/formvibes';
import { View, Hide } from '@element-plus/icons-vue';

const store = useFVStore();
const { fvDataProfile,generalStates } = storeToRefs(store);
const props = defineProps(['updateShowColumns']);
const i18n = window.fvGlobalVar?.i18n;
const showSubColumns = ref(fvDataProfile.value.fv_fields.cols_on_expand ? true : false);

watch([showSubColumns],() => {
    props.updateShowColumns(showSubColumns.value)
} );

const changeVisible = (e) => {
    e.visible = !e.visible
}
const allowDrop = (draggingNode, dropNode, type) => {
    if(type === 'inner'){
        return false;
    }
    return true
}
</script>
<template>
    <div>
        <el-tree
            :allow-drop="allowDrop"
            allow-drag="true"
            draggable
            default-expand-all
            node-key="id"
            :data="generalStates.columns"
        >
            <template  #default="{ node, data }">
                <div class="fv-settings-item">
                    {{ data.colKey }}
                    <el-input v-model="data.alias" placeholder="Please input" />
                    <!-- <el-checkbox v-model="data.visible" size="large" /> -->
                    <span >
                        <el-button v-if="data.visible" @click="changeVisible(data)" link >
                            <el-icon>
                                <View />
                            </el-icon>
                        </el-button>
                        <el-button v-if="!data.visible" @click="changeVisible(data)" link :class="{'fv-hide-col-active': !data.visible}">
                            <el-icon>
                                <Hide />
                            </el-icon>
                        </el-button>
                    </span>
                </div>
            </template>
        </el-tree>
        <div class="fv-form-row fv-dp-row-exapnd">
            <span class="fv-form-row-label">Show data on row expand</span>
            <el-switch v-model="showSubColumns" />
        </div>
        <div class="fv-form-row" v-if="showSubColumns">
            <span class="fv-form-row-label">Field to display on row expand</span>
        </div>
        <div class="fv-export-setting-col-header" v-if="showSubColumns">
            <span class="fv-setting-label">
                {{i18n?.field_name}}
            </span>
            <span>
                {{i18n?.column_label}}
            </span>
            <span>
                {{i18n?.column_visibility}}
            </span>
        </div>
        <el-tree
            :allow-drop="allowDrop"
            allow-drag="true"
            draggable
            default-expand-all
            node-key="ids"
            :data="generalStates.subComponentColumns"
            v-if="showSubColumns"
        >
            <template #default="{ node, data }">
                <div class="fv-settings-item">
                    {{ data.colKey }}
                    <el-input v-model="data.alias" placeholder="Please input" />
                    <!-- <el-checkbox v-model="data.visible" size="large" /> -->
                    <span >
                        <el-button v-if="data.visible" @click="changeVisible(data)" link  >
                            <el-icon>
                                <View />
                            </el-icon>
                        </el-button>
                        <el-button v-if="!data.visible" @click="changeVisible(data)" link :class="{'fv-hide-col-active': !data.visible}">
                            <el-icon>
                                <Hide />
                            </el-icon>
                        </el-button>
                    </span>
                </div>
            </template>
        </el-tree>
    </div>
</template>