<script setup>
import { watch, ref, onMounted, watchEffect } from 'vue';
import { storeToRefs } from "pinia";
import { useFVStore } from '../../../stores/formvibes';
import DataFilter from './filter/filter.vue';
import Fields from './fields.vue';
import { axiosPost } from '../../../Axios/post';
import { Hide,View } from '@element-plus/icons-vue';
import tableSettings from './table-settings.vue';
import SearchSettings from './search-setting.vue';
import CounterSettings from './counter-settings.vue';
import { shortcuts } from '../../../stores/utils';
const store = useFVStore();
const { formsSelector,defaultDates,fvDataProfile, generalStates } = storeToRefs(store);

const i18n = window.fvGlobalVar?.i18n;
const ajax_nonce = window.fvGlobalVar.ajax_nonce;
const fvDateRange = ref(defaultDates.value);
const preset = ref('Custom');
const displayType = ref('table');
const selectedForm = ref('');
const forms = formsSelector.value;
const form = ref('');
const plugin = ref('');
const savedFormData = ref(fvDataProfile.value?.fv_data_source?.split(':'));
const columns = ref(fvDataProfile.value?.fv_fields?.cols || []);
const subComponentColumns = ref(fvDataProfile.value?.fv_fields?.cols_on_expand || fvDataProfile.value?.fv_fields?.
cols || []);
const showSubColumns = ref(fvDataProfile.value.fv_fields.cols_on_expand ? true : false);
const displayTypeOptions = [
	{ value: 'table', label: i18n?.table, icon: '' },
	{ value: 'counter', label: i18n?.counter, icon: '' },
];
const filters = ref([fvDataProfile.value.fv_filters]);

onMounted(() => {
    let dataSource = fvDataProfile.value.fv_data_source?.split(':');
    displayType.value = fvDataProfile.value.fv_output_mode || 'table';

    if(!dataSource[0]){
        const firstForm = forms[0]['options'][0];

        dataSource[0] = firstForm.plugin;
        dataSource[1] = firstForm.value;

        selectedForm.value = firstForm.value;
    }
    plugin.value = dataSource[0] || '';
    form.value = dataSource[1] || '';
    selectedForm.value = dataSource[1] || '';

    const dates = fvDataProfile.value.fv_date_range;

    let shortcut = '';
    if(!dates){
        shortcut = shortcuts.filter((shortcut) => {
            return shortcut.text === 'This Year';
        })[0]
    }
    else{
        shortcut = shortcuts.filter((shortcut) => {
            return shortcut.text === dates.queryType.replaceAll('_', ' ');
        })[0]
    }

    if(shortcut && shortcut.text !== 'Custom') {
        preset.value = dates.queryType;
        fvDateRange.value = [
            shortcut.value()[0].format('YYYY-MM-DD'),
            shortcut.value()[1].format('YYYY-MM-DD')
        ];
    }else{
        preset.value = 'Custom';
        fvDateRange.value = [
            dates.fromDate,
            dates.toDate
        ];
    }

    if(fvDataProfile.value.fv_data_profile_search){
        fvDataProfile.value.fv_data_profile_search = JSON.parse(fvDataProfile.value.fv_data_profile_search);
    }

    if(!fvDataProfile.value.fv_data_profile_search){
        fvDataProfile.value.fv_data_profile_search = {
            columns: [],
            operator: 'LIKE',
            displayOnFrontend: false,
            alignment: 'right',
            isSearch: false,
        }
    }
});

watch([fvDateRange], async () => {
    const shortcut = shortcuts.filter((shortcut) => {
        const [start, end] = shortcut.value();
        return start.format('YYYY-MM-DD') === fvDateRange.value[0] && end.format('YYYY-MM-DD') === fvDateRange.value[1];
    })[0];

    if(!shortcut) {
      preset.value = 'Custom';
    }
    else{
      preset.value = shortcut.text.replaceAll(' ', '_');
    }
});

const onChangeForm = async (id, e) => {
    const formSelected = forms.filter((form) => form.label === e.label)[0].options.filter((fm) => fm.value === id)[0];
    form.value = formSelected.value;
    plugin.value = formSelected.plugin;
    fvDataProfile.value.fv_filters = [{
            filter: '',
            key: '',
            operator: 'LIKE',
            value: '',
    }];

}
watch([selectedForm,displayType], async () => {
    getColumns();
})

const updateShowColumns = (val) => {
    showSubColumns.value = val;
}

const getColumns = async () => {

    const { data } = await axiosPost({
        action: 'fv_get_columns',
        queryParams: {
            formId: form.value,
            plugin: plugin.value,
        },
    });
    let isOldColumns = false;

    if (
        savedFormData.value.length > 1 &&
        // eslint-disable-next-line eqeqeq
        plugin.value == savedFormData.value[0] &&
        // eslint-disable-next-line eqeqeq
        form.value == savedFormData.value[1] &&
        fvDataProfile.value?.fv_output_mode == 'table'
    ) {
        isOldColumns = true;
    }

    const savedCols = fvDataProfile.value?.fv_fields?.cols;
    const subSavedCols = fvDataProfile.value?.fv_fields?.cols_on_expand || fvDataProfile.value?.fv_fields?.cols || [];
    
    if (isOldColumns) {
        data.columns.forEach((col) => {
            if ( savedCols && !savedCols?.find((sCol) => sCol.colKey === col.colKey))
            {
                savedCols.push({
                    ...col,
                });
            }
        });

        data.columns.forEach((col) => {
            if (!subSavedCols.find((sCol) => sCol.colKey === col.colKey)) {
                subSavedCols.push({
                    ...col,
                });
            }
        });
    }

    if(fvDataProfile.value.fv_fields){
        fvDataProfile.value.fv_fields.cols = isOldColumns ? savedCols : data.columns;
    }
    else{
        fvDataProfile.value.fv_fields = {
            cols: isOldColumns ? savedCols : data.columns,
        }
    }
    generalStates.value.columns = isOldColumns ? savedCols : data.columns;
    generalStates.value.subComponentColumns = isOldColumns ? subSavedCols : data.columns;

    generalStates.value.columns = JSON.parse(JSON.stringify(generalStates.value.columns))
    generalStates.value.subComponentColumns = JSON.parse(JSON.stringify(generalStates.value.subComponentColumns))
};
</script>
<template>
    <el-config-provider>
        <input name="fv_table_settings" :value="`${JSON.stringify(fvDataProfile.fv_table_settings)}`" type="hidden" />
        <input name="fv_data_profile_search" :value="`${JSON.stringify(fvDataProfile.fv_data_profile_search)}`" type="hidden" />
        <input name="fv_data_source" :value="`${plugin}:${form}`" type="hidden" />
        <input name="ajaxNonce" :value="`${ajax_nonce}`" type="hidden" />
        <input name="fv_output_mode" :value="displayType" type="hidden" />
        <input name="fv_date_range[queryType]" :value="preset" type="hidden" />
        <input name="fv_date_range[fromDate]" :value="fvDateRange[0]" type="hidden" />
        <input name="fv_date_range[toDate]" :value="fvDateRange[1]" type="hidden" />
        <input name="fv_fields" :value="`${JSON.stringify(generalStates.columns)}`" type="hidden" />
        <input name="fv_show_on_expand" :value="showSubColumns" type="hidden" />
        <input name="fv_expand_fields" :value="`${JSON.stringify(generalStates.subComponentColumns)}`" type="hidden" />
        <input name="fv_filters" :value="`${JSON.stringify(fvDataProfile.fv_filters)}`" type="hidden" />
        <input name="fv_filter_relation" :value="fvDataProfile.fv_filter_relation" type="hidden" />

        <input name="fv_is_count_message" :value="fvDataProfile.fv_is_count_message" type="hidden" />
        <input name="fv_count_message" :value="fvDataProfile.fv_counter_message" type="hidden" />
        <input
				name="fv_status"
				:value="`${JSON.stringify(
					Object.values(fvDataProfile.fv_status).map(
						({ value, key }) => ({
							label: value,
							value: key,
						})
					)
				)}`"
				type="hidden"
			/>
        <div>
            <div class="fv-export-header" style="display:flex; align-items: center; gap: 20px;">
                <span>Display Type</span>
                <el-select v-model="displayType" placeholder="Select">
                    <el-option
                        v-for="item in displayTypeOptions"
                        :key="item.value"
                        :label="item.label"
                        :value="item.value"
                    />
                </el-select>
            </div>
            <div class="fv-export-content">
                <el-tabs tab-position="left">
                    <el-tab-pane label="Data Source" class="fv-settings-export-ds">
                        <div class="fv-form-row">
                            <span>Form</span>
                            <el-select v-model="selectedForm" placeholder="Select">
                                <el-option-group
                                    v-for="group in forms"
                                    :key="group.label"
                                    :label="group.label"
                                    >
                                    <el-option
                                        v-for="item in group.options"
                                        :key="item.value"
                                        :label="item.label"
                                        :value="item.value.toString()"
                                        @click="(e) => onChangeForm(item.value,group)"
                                    />
                                </el-option-group>
                            </el-select>
                        </div>
                        <div class="fv-form-row">
                            <span>Date Range</span>
                            <el-date-picker
                                v-model="fvDateRange"
                                type="daterange"
                                unlink-panels
                                range-separator="To"
                                start-placeholder="Start Date"
                                end-placeholder="End date"
                                popper-class="wml-date-picker-popup"
                                size="default"
                                :shortcuts="shortcuts"
                                value-format="YYYY-MM-DD"
                                format="DD/MM/YYYY"
                                :clearable="false"
                            />
                        </div>
                        <div class="fv-form-row" v-if="displayType == 'table'">
                            <span>Search</span>
                            <el-switch v-model="fvDataProfile.fv_data_profile_search.isSearch" />
                        </div>
                        <div class="fv-export-filter-section">
                            <span class="fv-export-filter-heading">Data Filter</span>
                            <DataFilter :selectedForm="selectedForm" />
                        </div>
                        
                    </el-tab-pane>
                    <el-tab-pane label="Fields" v-if="displayType == 'table'">
                        <div class="fv-export-setting-col-header">
                            <span class="fv-setting-label">
                                {{i18n?.field_name}}
                            </span>
                            <span>
                                {{i18n?.column_label}}
                            </span>
                            <span>
                                {{i18n?.column_visibility}}
                            </span>
                        </div>
                        <Fields :updateShowColumns="updateShowColumns" />
                    </el-tab-pane>
                    <el-tab-pane label="Table Settings" v-if="displayType == 'table'">
                        <tableSettings />
                    </el-tab-pane>
                    <el-tab-pane label="Search" v-if="displayType == 'table' && fvDataProfile.fv_data_profile_search.isSearch">
                        <SearchSettings />
                    </el-tab-pane>
                    <el-tab-pane label="Counter Settings" v-if="displayType == 'counter'">
                        <CounterSettings />
                    </el-tab-pane>
                </el-tabs>
            </div>
        </div>
    </el-config-provider>
</template>