<script setup>
import { watch, ref, onMounted } from 'vue';
import { storeToRefs } from "pinia";
import { useFVStore } from '../../../stores/formvibes';

const store = useFVStore();
const i18n = window.fvGlobalVar?.i18n;
const {fvDataProfile} = storeToRefs(store);
const tokens = window.fvdata.tokens
const isShowMessage = ref(false);

onMounted(() => {
    const cm = fvDataProfile.value?.fv_is_count_message === 'true' || fvDataProfile.value.fv_counter_message !== '';

    isShowMessage.value = cm;
});

watch([isShowMessage],()=>{
    fvDataProfile.value.fv_is_count_message = isShowMessage.value
})

</script>
<template>
    <div>
        <div class="fv-row">
            <div>
                {{i18n?.custom_message}}
            </div>
            <div>
                <el-switch v-model="isShowMessage" />
            </div>
        </div>
        <div class="fv-row" v-if="isShowMessage">
            <span>
                Message
            </span>
            <div v-if="isShowMessage">
                <el-input
                    v-model="fvDataProfile.fv_counter_message"
                    :rows="4"
                    type="textarea"
                    placeholder="message"
                />
            </div>
        </div>
        <div class="fv-row" v-if="isShowMessage">
            <p>Tags:</p>
            <p v-for="token in tokens" :key="token.hint">
                <span>{{token.label}} : </span>
                <span>{{token.hint}} </span>
            </p>
        </div>
    </div>
</template>