<script setup>
import { watch, ref, onMounted } from 'vue';
import { storeToRefs } from "pinia";
import { useFVStore } from '../../../stores/formvibes';
const i18n = window.fvGlobalVar?.i18n;
const store = useFVStore();
const {fvDataProfile} = storeToRefs(store);

const settings = ref(fvDataProfile.value?.fv_table_settings || {
			rows: 5,
			show_pagination: true,
			show_limit_box: true,
			sr_no: true,
			sr_no_title: 'S/N',
		});

onMounted(() => {
   if(!fvDataProfile.value.fv_table_settings){
       fvDataProfile.value.fv_table_settings = settings.value;
   }
});
</script>
<template>
    <div>
        Table Settings
        <div class="fv-form-row">
            <span>{{i18n?.default_rows}}</span>
            <span>
                <el-select v-model="fvDataProfile.fv_table_settings.rows" placeholder="5">
                    <el-option label="5" value="5"/>
                    <el-option label="10" value="10"/>
                    <el-option label="20" value="20"/>
                    <el-option label="50" value="50"/>
                    <el-option label="100" value="100"/>
                </el-select>
            </span>
        </div>
        <div class="fv-form-row">
            <span>{{i18n?.pagination}}</span>
            <span>
                <el-switch v-model="fvDataProfile.fv_table_settings.show_pagination" />
            </span>
        </div>
        <div class="fv-form-row">
            <span>{{ i18n?.limit }}</span>
            <span>
                <el-switch v-model="fvDataProfile.fv_table_settings.show_limit_box" />
            </span>
        </div>
        <div class="fv-form-row">
            <span>{{i18n?.ssnc}}</span>
            <span>
                <el-switch v-model="fvDataProfile.fv_table_settings.sr_no" />
            </span>
        </div>
        <div class="fv-form-row" v-if="fvDataProfile.fv_table_settings.sr_no">
            <span>{{ i18n?.serial_number_column_title }}</span>
            <span>
                <el-input v-model="fvDataProfile.fv_table_settings.sr_no_title" />
            </span>
        </div>
        
    </div>
</template>