<script setup>
import { watch, ref, onMounted } from 'vue';
import { storeToRefs } from "pinia";
import { useFVStore } from '../../../stores/formvibes';

const store = useFVStore();
const i18n = window.fvGlobalVar?.i18n;
const {fvDataProfile,generalStates} = storeToRefs(store);

const entryTableFields = window.fvdata?.entry_table_fields || [];
const settings = ref([]);

onMounted(() => {
    if(fvDataProfile.value.fv_data_profile_search){
        settings.value = fvDataProfile.value.fv_data_profile_search;
    }
    else{
        settings.value = {
            columns: [],
            operator: 'equal',
            displayOnFrontend: false,
            alignment: 'left',
            isSearch: false,
        };
    }
});
const operatorOptions = [
        {
            value: 'equal', label: 'Equal', operator: '='
        },
        {
            value: 'not_equal', label: 'Not Equal', operator: '!='
        },
        {
            value: 'LIKE', label: 'Contain', operator: 'LIKE'
        },
        {
            value: 'NOT LIKE', label: 'Not Contain', operator: 'NOT LIKE'
        }
];
const alignments = [
	{
		value: 'left',
		label: 'Left',
	},
	{
		value: 'right',
		label: 'Right',
	},
];
watch([settings],() =>{
    fvDataProfile.value.fv_data_profile_search = settings.value
},{deep:true});

</script>
<template>
    <div>
        <div class="fv-form-row">
            <span>{{ i18n?.search_columns }}</span>
            <div>
                <el-select v-model="settings.columns" placeholder="Select" multiple>
                    <el-option
                        v-for="item in generalStates.columns
							.map((col) => ({
								value: col.colKey,
								label: col.alias,
							}))
							.filter((c) => !entryTableFields.includes(c.value))"
                        :key="item.value"
                        :label="item.label"
                        :value="item.value"
                    />
                </el-select>
            </div>
        </div>
        <div class="fv-form-row">
            <span>
                {{ i18n?.search_operator }}
            </span>
            <div>
                <el-select v-model="settings.operator" placeholder="Select">
                    <el-option
                    v-for="item in operatorOptions"
                    :key="item.value"
                    :label="item.label"
                    :value="item.value"
                    />
                </el-select>
            </div>
        </div>
        <div class="fv-form-row">
            <span>{{i18n?.display_filter_on_frontend}}</span>
            <div>
                <el-switch v-model="settings.displayOnFrontend" />
            </div>
        </div>
        <div class="fv-form-row">
            <span>
                {{ i18n?.alignment }}
            </span>
            <div>
                <el-select v-model="settings.alignment" placeholder="Select">
                    <el-option
                    v-for="item in alignments"
                    :key="item.value"
                    :label="item.label"
                    :value="item.value"
                    />
                </el-select>
            </div>
        </div>
    </div>
</template>